INSERT INTO `documents` VALUES
(15,'BOQ_ESTHER_LIM_TEST_SYNC_SERVER','DOC-20260215-1300','boq','approved','Operations',NULL,NULL,NULL,'\n                <style>\n                    * { margin: 0; padding: 0; box-sizing: border-box; }\n                    html, body { width: 100%; height: 100%; }\n                    body { \n                        font-family: Arial, sans-serif; \n                        background-color: white; \n                        padding: 20px; \n                        font-size: 11px;\n                        line-height: 1.4;\n                    }\n                    .container { \n                        max-width: 900px; \n                        margin: 0 auto; \n                        background-color: white; \n                        padding: 20px;\n                    }\n                    input[type=\"text\"], \n                    input[type=\"number\"], \n                    input[type=\"date\"],\n                    textarea,\n                    select {\n                        border: none !important;\n                        background: transparent !important;\n                        font-family: Arial, sans-serif;\n                        font-size: 11px;\n                        padding: 2px !important;\n                        margin: 0 !important;\n                    }\n                    input[type=\"text\"]::placeholder,\n                    input[type=\"number\"]::placeholder,\n                    textarea::placeholder {\n                        color: #999;\n                    }\n                    .header-section { \n                        margin-bottom: 15px; \n                        border-bottom: 2px solid #000; \n                        padding-bottom: 10px; \n                    }\n                    .header-section div { \n                        margin: 2px 0; \n                        line-height: 1.3;\n                    }\n                    .header-section strong { \n                        text-decoration: underline; \n                    }\n                    table { \n                        width: 100%; \n                        border-collapse: collapse; \n                        margin: 10px 0; \n                        page-break-inside: avoid;\n                    }\n                    table th { \n                        background-color: #FFFF00 !important; \n                        font-weight: bold; \n                        text-align: center; \n                        border: 1px solid #000; \n                        padding: 6px 4px;\n                        font-size: 10px;\n                    }\n                    table td { \n                        border: 1px solid #000; \n                        padding: 4px 6px; \n                        text-align: left;\n                        background-color: white !important;\n                    }\n                    table td input,\n                    table td textarea,\n                    table td select {\n                        width: 100%;\n                        border: none !important;\n                        background: transparent !important;\n                    }\n                    .total-row td { \n                        background-color: #FFFF00 !important; \n                        font-weight: bold;\n                    }\n                    .grand-total-row td { \n                        background-color: #FFFF00 !important; \n                        font-weight: bold; \n                        font-size: 11px;\n                    }\n                    .section-header { \n                        background-color: #f0f0f0; \n                        font-weight: bold; \n                        margin-top: 10px; \n                        padding: 6px; \n                        border: 1px solid #000;\n                    }\n                    h1, h2 { \n                        text-align: center; \n                        margin: 10px 0; \n                        font-size: 14px;\n                        font-weight: bold;\n                    }\n                    h3 { \n                        font-size: 12px;\n                        margin: 8px 0 4px 0;\n                    }\n                    .perimeter-section { \n                        margin: 8px 0; \n                        font-weight: bold; \n                    }\n                    .signature-section {\n                        margin-top: 20px;\n                    }\n                    .signature-line {\n                        display: inline-block;\n                        width: 200px;\n                        border-bottom: 1px solid #000;\n                        margin: 20px 20px 0 0;\n                        text-align: center;\n                    }\n                    @media print { \n                        body { margin: 0; padding: 0; }\n                    }\n                </style>\n                \n        <!-- Header -->\n          <!-- Header -->\n        <div class=\"header\">\n            <hr style=\"border: 1.5px solid #ffd102; width: 100%; margin: 0 auto 15px auto;\">\n\n            <h2>BILL OF QUANTITIES</h2><br>\n         \n            <hr style=\"border: 1.5px solid #ffd102; width: 100%; margin: 0 auto 15px auto;\">\n        \n\n\n        </div>\n\n        <!-- Project Information -->\n        <div class=\"project-info\">\n            <div class=\"info-group\">\n                <label>Department:</label>\n                <select id=\"projectDepartment\">Operations</select>\n            </div>\n            <div class=\"info-group\">\n                <label>Project Name:</label>\n                <input type=\"text\" id=\"projectName\" placeholder=\"Enter project name\" value=\"TOMSWORLD\">\n            </div>\n            <div class=\"info-group\">\n                <label>Location:</label>\n                <input type=\"text\" id=\"projectLocation\" placeholder=\"Enter location\" value=\"Pasig City Metro Manila\">\n            </div>\n            <div class=\"info-group\">\n                <label>Total Floor Area:</label>\n                <input type=\"text\" id=\"projectFloorArea\" placeholder=\"Enter total floor area\" value=\"14400\">\n            </div>\n            <div class=\"info-group\">\n                <label>Date:</label>\n                <input type=\"date\" id=\"dateField\" value=\"2026-02-13\">\n            </div>\n            <div class=\"info-group\">\n                <label>Reference no:</label>\n                <input type=\"text\" id=\"referenceNo\" readonly=\"\" value=\"MCE-20260215120909\">\n            </div>\n        </div>\n        \n \n        <script>\n        // Auto-generate Reference No in format MCE-yyyymonthdaytime\n        function pad(n) { return n < 10 ? \'0\' + n : n; }\n        function generateReferenceNo() {\n            var now = new Date();\n            var yyyy = now.getFullYear();\n            var mm = pad(now.getMonth() + 1);\n            var dd = pad(now.getDate());\n            var hh = pad(now.getHours());\n            var min = pad(now.getMinutes());\n            var ss = pad(now.getSeconds());\n            var ref = `MCE-${yyyy}${mm}${dd}${hh}${min}${ss}`;\n            document.getElementById(\'referenceNo\').value = ref;\n        }\n        window.addEventListener(\'DOMContentLoaded\', generateReferenceNo);\n        </script>\n\n               <!-- Bill of Materials -->\n        <div style=\"font-weight: bold; margin-bottom: 10px;\">MATERIALS &amp; LABOR COST ESTIMATE: BILL OF QUANTITIES SECTION</div>\n\n        <!-- Panel Board and Circuit Breakers -->\n        <div id=\"panelSection\" class=\"bom-section\">\n        <div class=\"section-title\">PANEL BOARD AND CIRCUIT BREAKERS:</div>\n        <table id=\"panelTable\">\n            <thead>\n                <tr>\n                    <th rowspan=\"2\" style=\"width: 25%;\">ITEM DESCRIPTION</th>\n                    <th rowspan=\"2\" style=\"width: 8%;\">UNIT</th>\n                    <th rowspan=\"2\" style=\"width: 7