     }\\n                    .header-section { \\n                        margin-bottom: 15px; \\n                        border-bottom: 2px solid #000; \\n                        padding-bottom: 10px; \\n                    }\\n                    .header-section div { \\n                        margin: 2px 0; \\n                        line-height: 1.3;\\n                    }\\n                    .header-section strong { \\n                        text-decoration: underline; \\n                    }\\n                    table { \\n                        width: 100%; \\n                        border-collapse: collapse; \\n                        margin: 10px 0; \\n                        page-break-inside: avoid;\\n                    }\\n                    table th { \\n                        background-color: #FFFF00 !important; \\n                        font-weight: bold; \\n                        text-align: center; \\n                        border: 1px solid #000; \\n                        padding: 6px 4px;\\n                        font-size: 10px;\\n                    }\\n                    table td { \\n                        border: 1px solid #000; \\n                        padding: 4px 6px; \\n                        text-align: left;\\n                        background-color: white !important;\\n                    }\\n                    table td input,\\n                    table td textarea,\\n                    table td select {\\n                        width: 100%;\\n                        border: none !important;\\n                        background: transparent !important;\\n                    }\\n                    .total-row td { \\n                        background-color: #FFFF00 !important; \\n                        font-weight: bold;\\n                    }\\n                    .grand-total-row td { \\n                        background-color: #FFFF00 !important; \\n                        font-weight: bold; \\n       